import{_ as l,c as r,o as a,ag as e}from"./chunks/framework.Bkod66qp.js";const c=JSON.parse('{"title":"직원 채용에 관한 내규","description":"","frontmatter":{"title":"직원 채용에 관한 내규","subtitle":"","doc_id":"","last_update":"2025-08-12","author":"","categories":[],"tags":[]},"headers":[],"relativePath":"regulation/305_직원 채용에 관한 내규(250812)★.md","filePath":"regulation/305_직원 채용에 관한 내규(250812)★.md"}'),o={name:"regulation/305_직원 채용에 관한 내규(250812)★.md"};function d(i,t,n,s,p,g){return a(),r("div",null,t[0]||(t[0]=[e(`<h1 id="law-title" class="center" tabindex="-1">직원 채용에 관한 내규 <a class="header-anchor" href="#law-title" aria-label="Permalink to &quot;직원 채용에 관한 내규 {#law-title .center}&quot;">​</a></h1><div style="text-align:right;"><pre style="display:inline-block;margin:0;white-space:pre;font-family:monospace;">제정 2010.   8.  16
개정 2011.   3.  22
개정 2013.  10.  31
개정 2015.  11.  16
개정 2018.   8.  13
개정 2018.  10.  10
개정 2019.   8.  14
개정 2021.   5.   6
개정 2022.   4.   4
개정 2022.   8.  23
개정 2023.   6.  29
개정 2024.   2.   6
개정 2024.   7.  24
개정 2024.  12.  30
개정 2025.   5.  20
개정 2025.   8.  12</pre></div><h2 id="제1장-총-칙" tabindex="-1">제1장 총 칙 <a class="header-anchor" href="#제1장-총-칙" aria-label="Permalink to &quot;제1장 총 칙&quot;">​</a></h2><h2 id="article1" class="sr-only" tabindex="-1">제1조 (목적) <a class="header-anchor" href="#article1" aria-label="Permalink to &quot;제1조 (목적) {#article1 .sr-only}&quot;">​</a></h2><p><strong>제1조(목적)</strong> 이 내규는 재단법인 서울문화재단(이하 “재단”이라 한다)의 인사규정 제5조의 공개채용에 관하여 필요한 사항을 정함을 목적으로 한다. &lt;개정 2013. 10. 31.&gt;</p><h2 id="article2" class="sr-only" tabindex="-1">제2조 (채용계획 수립) <a class="header-anchor" href="#article2" aria-label="Permalink to &quot;제2조 (채용계획 수립) {#article2 .sr-only}&quot;">​</a></h2><p><strong>제2조(채용계획 수립)</strong> ① 대표이사는 직원을 채용하려는 경우, 채용계획 등에 대해 서울특별시장에게 사전 협의하여야 한다. 다만, 기간의 정함이 있는 근로자(비정규직 근로자) 채용의 경우 사전협의 생략이 가능하다. 인력수요의 변화 등으로 채용계획이 변경된 경우에는 서울특별시장에게 사전 협의하여야 한다. 서울특별시장이 채용계획에 대하여 통합채용 등 의견을 제시할 경우, 대표이사는 서울특별시장이 제시한 의견을 원칙적으로 반영하여야 한다. &lt;신설 2018. 10. 10.&gt;, &lt;개정 2019. 8. 14, 2025. 08. 12.&gt;<br> ② 채용계획에는 채용의 필요성, 예상결원 및 정·현원 현황, 채용인원, 응시자격 요건, 필기시험 여부, 서류전형 심사 기준, 전형별 합격배수, 면접방법, 시험단계별 시험위원 위촉 계획을 포함하여야 한다. &lt;신설 2018. 10. 10.&gt;, &lt;개정 2024. 7. 24.&gt;</p><h2 id="article3" class="sr-only" tabindex="-1">제3조 (공개경쟁 채용시험의 공고) <a class="header-anchor" href="#article3" aria-label="Permalink to &quot;제3조 (공개경쟁 채용시험의 공고) {#article3 .sr-only}&quot;">​</a></h2><p><strong>제3조(공개경쟁 채용시험의 공고)</strong> ① 공개경쟁 채용시험을 실시할 때에는 모집 직무, 임용 예정직급, 응시자격, 시험의 방법·시기, 채용예정인원, 시험과목 및 배점비율, 서류전형 및 면접시험의 평가 기준, 전형별 합격배수, 가점기준, 합격자발표 시기·장소 및 방법, 응시원서의 발급장소 및 접수장소와 그 기한, 응시자의 부정합격 확인 시 채용이 취소될 수 있다는 내용, 그 밖에 시험실시에 필요한 사항을 응시서류 접수마감 20일전(선발예정 인원이 10명 이하일 때에는 10일전)까지 공고하여야 한다. 다만, 공고기간에 초일은 불산입하며, 공휴일은 포함하되, 접수기간은 가급적 5일 이상(토ㆍ일요일 등 공휴일 제외)으로 한다. &lt;개정 2011. 3. 22., 2015. 11. 16., 2018. 08. 13., 2018. 10. 10., 2019. 8. 14., 2024. 12. 30., 2025. 5. 20.&gt;<br> ② 제1항에 따른 공고내용을 변경하고자 할 때에는 시험시행일 7일전까지 그 변경내용을 공고하여야 한다. 변경공고 내용 중 시험과목 및 배점비율, 전형별 합격배수, 가점 기준을 변경할 경우에는 인사위원회의 심의·의결 후 서울특별시장과 협의하여야 한다. &lt;개정 2018. 10. 10., 2023. 6. 29.&gt;<br> ③ 서울특별시의 인터넷 홈페이지, 행정안전부장관이 정하는 통합공개시스템에 공고하여야 하며, 관련 협회·단체 및 대학 등에 모집공고문을 송부하여 많은 적격자가 응모할 수 있도록 노력하여야 한다. &lt;신설 2018. 10. 10.&gt;, &lt;개정 2019. 8. 14., 2021. 5. 6.&gt;<br> ④ 공고의 결과 응시인원이 선발예정인원과 같거나 선발예정인원보다 적은 경우(응시자가 없는 경우를 포함한다)에는 시험기일을 다시 정하여 재공고할 수 있다. (당초 공고내용과 동일한 경우에는 제2조제1항에 따른 서울특별시와의 사전협의는 거친 것으로 본다) &lt;신설 2021. 5. 6.&gt;</p><h2 id="article4" class="sr-only" tabindex="-1">제4조 (시험의 방법) <a class="header-anchor" href="#article4" aria-label="Permalink to &quot;제4조 (시험의 방법) {#article4 .sr-only}&quot;">​</a></h2><p><strong>제4조(시험의 방법)</strong> ① 공개경쟁 채용시험은 다음 각 호의 방법에 의한 서류전형, 필기시험, 면접시험 및 종합인적성검사에 의한다.</p><ol><li>서류전형은 직무수행에 관련되는 역량 및 자격 등을 심사한다. 직무능력 중심의 채용을 위해 직무수행 능력과 관계없는 학력, 신체조건 등 편견을 불러일으킬 수 있는 요소는 배제한다. 다만 채용 직무를 수행하는데 반드시 필요하거나 응시자격 및 우대사항에 대한 사항 등을 확인하기 위해 필요한 경우에는 그러하지 아니한다. &lt;개정 2018. 10. 10., 2024. 12. 30., 2025. 5. 20.&gt;</li><li>필기시험은 직무수행에 필요한 지식 및 그 응용능력을 NCS 직업기초능력평가를 통해 검정하며, 필요 시 직무지식평가를 추가로 실시할 수 있다. &lt;개정 2024. 12. 30.&gt;</li><li>면접시험은 직무수행에 필요한 역량, 인성 및 적격성을 검정하며, 필요한 경우 실무면접 및 최종면접으로 나누어 단계별로 실시할 수 있다. 면접은 구조화된 면접(경험·상황·발표·토론면접 등)을 실시하며 공정한 평가가 되도록 노력하여야 한다. 면접위원에게 응시자의 학력, 출신지역 등 인적사항 관련 정보제공 금지, 연령·성별·학력 등 차별적 소지가 있는 질문 금지, 평정방법, 합격자 결정방법, 면접 진행절차, 직무능력 중심의 채용 등 면접시행에 필요한 사전 면접교육을 실시하여야 한다. 면접 응시자의 성별을 기록·유지하고, 기관 자체 모니터링을 실시하여 성차별이 방지되도록 노력하여야 한다. &lt;개정 2018. 10. 10., 2021. 5. 6., 2024. 12. 30., 2025. 5. 20.&gt;</li><li>종합인적성검사는 직무수행에 필요한 적성과 자질 및 인성을 종합 검정한다. &lt;개정 2021. 5. 6.&gt;<br> ② 다음 각 호의 경우, 사전협의 통보기한 단축 및 협의 내용(방식) 간소화, 공고기간 단축, 시험단계 축소, 시험위원 중 외부전문가 비율 조정(예시 : 1/2 이상→ 1명 이상) 등 채용절차를 간소화할 수 있다. 이 경우에도 공개경쟁시험 채용 원칙을 유지해야 하며, 채용절차 간소화의 구체적인 내용과 범위는 서울특별시와 협의, 시험 성격, 재단의 채용사정, 채용 예정 직위의 특성 등을 종합 고려하여 판단 가능하다. &lt;신설 2018. 10. 10.&gt;, &lt;개정 2024. 2. 6.&gt;</li><li>연중 9개월 미만이거나 사업의 완료기간이 2년 이하*로 명확한 일시·간헐적 업무를 위해 비정규직을 채용하는 경우 (예시 : 초단시간 근로자, 일용직 근로자 채용 등)</li></ol><ul><li>「기간제 및 단시간근로자 보호 등에 관한 법률」제4조 제1항 각호에 해당하는 경우 예외적으로 2년 초과 가능&lt;신설 2024. 2. 6.&gt;</li></ul><ol start="2"><li>국민의 생명·안전과 관련하여 비상상황에 대응하기 위하여 비상상황* 종료 시까지 한시적으로 근무할 인력을 긴급하게 채용하는 경우</li></ol><ul><li>비상상황 :「감염병의 예방 및 관리에 관한 법률」에 따른 감염병 위기경보　심각단계 발령,「재난 및 안전관리기본법」에 따른 재난사태 선포, 기타 이에 준하는 상황 &lt;신설 2024. 2. 6.&gt;<br> ③ 채용의 절차를 전문업체에 대행하거나 위탁하는 경우 해당 업체의 부정개입 차단과 정보유출 방지 방안 등을 마련하여야 한다. 위탁업체의 문제 인쇄·포장 등 채용의 절차에 인사 담당 직원을 입회담당자로 참여해야 한다. 위탁기관 등의 보안유지 위반 등에 대한 계약해지와 아울러 민사상 책임을 부과하고 형사고발 등의 조치를 하여야 한다. &lt;신설 2018. 10. 10.&gt;</li></ul><h2 id="article5" class="sr-only" tabindex="-1">제5조 (시험위원의 위촉) <a class="header-anchor" href="#article5" aria-label="Permalink to &quot;제5조 (시험위원의 위촉) {#article5 .sr-only}&quot;">​</a></h2><p><strong>제5조(시험위원의 위촉)</strong> ① 채용을 위한 서류전형 및 면접시험 시 외부 전문위원을 2분의 1이상으로 참여시켜야 하며, 이 경우 퇴직 후 3년이 경과하지 않은 자, 비상임 이사, 인사위원회 등 기관과 이해관계가 있거나 기타 공정한 심사를 기대하기 어려워 사실상 내부인으로 간주될 수 있는 자는 시험위원으로 참여할 수 없다. 다만, 서류전형에서 응시자격 등의 적격 여부만을 판단하는 경우에는 내부위원만으로도 가능하다. &lt;개정 2018. 10. 10., 2019. 8. 14., 2021. 5. 6., 2022. 4. 4.&gt;<br> ② 대표이사는 시험출제 및 채점, 그 밖에 시험 시행에 필요한 사항을 담당하는 시험위원으로 다음 각 호의 어느 하나에 해당하는 사람을 임명하거나 위촉할 수 있다.</p><ol><li>해당 직무분야에 관한 전문적인 학식 또는 능력을 가진 사람</li><li>시험 출제에 관하여 전문적인 학식 또는 능력을 가진 사람</li><li>임용예정 직무에 관한 실무에 정통한 사람<br> ③ 시험위원은 시험업무 처리 중 알게 된 비밀을 누설하여서는 아니 되며, 대표이사는 이를 담보하기 위하여 보안각서 등을 징구하여야 한다. 또한 채점표를 현장에서 직접 기재하여 서명 후 제출토록 하여야하며 비대면(온라인 시스템)으로 진행하는 경우에는 전자서명 등을 활용하여야 한다. &lt;개정 2021. 5. 6., 2022. 8. 23.&gt;<br> ④ 시험위원은 다음 각 호의 어느 하나에 해당하는 경우에는 시험과정에서 제척ㆍ회피하여야 하고, 기피될 수 있으며, 채용담당자는 사전에 시험위원들에게 공지하여야 한다. 다만, 외부 시험위원이 제척ㆍ기피ㆍ회피 조건에 해당되어 시험심사에 출석하지 못하게 되고, 해당 위원을 대체할 수 있는 시험위원을 선정하지 못하는 급박한 사정 등이 있는 경우에는 ‘외부전문위원의 2분의 1 이상 참여 의무’ 준수 여부를 판단 시, 해당위원이 참여한 것으로 간주한다. &lt;개정 2019. 8. 14.&gt;</li><li>시험위원 또는 그 배우자나 배우자였던 자가 응시자인 경우</li><li>시험응시자와 친족관계(혈족 및 인척)에 있거나 있었던 경우 &lt;개정 2018. 10. 10.&gt;</li><li>동일부서 근무경험관계 등 기타 이해당사자로서 공정을 기대하기 어려운 특별한 관계나 사정이 있는 경우 &lt;신설 2013. 10. 31.&gt;, &lt;개정 2018. 10. 10., 2025. 5. 20.&gt;<br> ⑤ 동일한 채용시험에는 필기시험 출제·채점위원, 면접시험위원, 서류전형 시험위원을 중복하여 위촉할 수 없다.&lt;개정 2018. 10. 10., 2019. 8. 14., 2024. 2. 6.&gt;<br> ⑥ 시험위원의 제척·기피·회피 관련 규정을 위반하거나,「지방공기업 블라인드 채용 가이드라인」을 위반한 사실이 있는 사람은 다시 시험위원으로 위촉할 수 없다. &lt;신설 2021. 5. 6.&gt;</li></ol><h2 id="article6" class="sr-only" tabindex="-1">제6조 (출제수준) <a class="header-anchor" href="#article6" aria-label="Permalink to &quot;제6조 (출제수준) {#article6 .sr-only}&quot;">​</a></h2><p><strong>제6조(출제수준)</strong> 공개경쟁 채용시험의 출제수준은 해당 직급에서의 직무 수행에 필요한 능력과 지식을 검정할 수 있는 정도로 한다. &lt;개정 2024. 12. 30.&gt;</p><h2 id="article7" class="sr-only" tabindex="-1">제7조 (시험의 합격결정) <a class="header-anchor" href="#article7" aria-label="Permalink to &quot;제7조 (시험의 합격결정) {#article7 .sr-only}&quot;">​</a></h2><p><strong>제7조(시험의 합격결정)</strong> ① 서류전형은 공고된 응시자격·경력 등 해당 직무와 적합한지 서면으로 심사하여 원점수가 평균 40% 이상인 자 중 합격결정을 하여야 한다. 다만, 응시인원을 고려하여 임용예정 직무에 적합한 기준에 따라 객관적이고 수긍가능한 기준으로 배수를 정하여 합격자를 결정할 수 있다. &lt;개정 2018. 10. 10., 2019. 8. 14., 2025. 5. 20.&gt;<br> ② 필기시험은 원점수가 평균 40% 이상인 자 중 부가 가점을 가산하여 선발예정인원의 5배수의 범위에서 고득점자 순으로 합격자를 결정한다. &lt;개정 2018. 10. 10., 2019. 8. 14., 2021. 5. 6., 2024. 2. 6., 2024. 7. 24., 2025. 5. 20.&gt;<br> ③ 종합인적성검사는 정규직 문화행정직에 한하여 시행하며 결과는 면접시험의 참고자료로 활용한다. &lt;개정 2021. 5. 6., 2024. 7. 24., 2025. 5. 20.&gt;<br> ④ 최종합격자 및 예비합격자는 면접시험의 응시자 중에서 부가 가점을 가산한 시험점수가 평균 60% 이상인 자 중 고득점자 순으로 결정한다. &lt;개정 2019. 8. 14., 2021. 5. 6., 2024. 2. 6., 2025. 5. 20.&gt;<br> ➄ 각 채용 단계별로 탈락자 중 일정 규모에 대하여 순번을 부여하여 향후 채용비리 발생 시 피해자 구제 등에 활용할 수 있도록 하여야 하며, 응시자에 대한 이의제기 절차를 안내하여야 한다. &lt;개정 2018. 10. 10., 2021. 5. 6., 2025. 5. 20.&gt;<br> ➅ 각 채용 단계별로 동점자가 발생하여 선발예정인원을 초과하는 경우에는 그 동점자를 모두 합격자로 하며, 이 경우 동점자의 계산은 소수점 이하 둘째 자리까지 한다. 다만, 면접시험 동점자가 발생하여 선발예정인원을 초과하는 경우에는 다음 각 호의 기준에 따라 합격자를 결정한다.&lt;신설 2021. 5. 6&gt;, &lt;개정 2025. 5. 20.&gt;</p><ol><li>동점자 중 「국가유공자 등 예우 및 지원에 관한 법률」에 따른 취업지원대상자</li><li>동점자 중 제1호에 해당하는 사람이 없거나 2명 이상인 경우 : 해당 채용회차의 전체 전형 평균 점수의 고득점자 순<br> ⑦ 예비합격자 규모는 선발예정인원의 2배수로 하며 채용절차 종료 후 심사위원 의결을 통해 예비합격자 순번을 정한다. 예비합격자 규모와 유효기간 등 주요내용을 채용공고 시 공개하며 후보합격자 명단은 공표하지 않는다. 최종합격자 발표일로부터 6개월 이내 동일 분야의 결원발생 시 그 순서에 따라 채용할 수 있으며, 추가 임용 시 최초 채용 선발분야 혹은 최초 작성된 예비합격자 명단의 순번을 임의로 변경할 수 없다. &lt;신설 2021. 5. 6.&gt;, &lt;개정 2022. 4. 4., 2025. 5. 20.&gt;<br> ⑧ 채용 전형 단계별로 관련 법령에 따른 장애인, 취업지원대상자 및 저소득층 등에 대하여 별표 1에 따라 부가가점을 가산할 수 있으며, 적용기준에 관하여 채용계획 및 채용공고문에 포함하여야 한다. &lt;신설 2025. 5. 20.&gt;</li></ol><h2 id="article7-2" class="sr-only" tabindex="-1">제7조의 2 (채용과정 공개) <a class="header-anchor" href="#article7-2" aria-label="Permalink to &quot;제7조의 2 (채용과정 공개) {#article7-2 .sr-only}&quot;">​</a></h2><p><strong>제7조의 2(채용과정 공개)</strong> 대표이사는 직원의 채용과정에 투명성과 공정성이 유지될 수 있도록 하여야 하며, 최종 합격자 발표일까지 선발인원, 합격인원, 응시인원, 합격선 등을 인터넷 홈페이지 등에 공개하여야 한다. 다만, 공개함으로써 개인의 신상이나 사생활을 침해할 우려가 있는 경우에는 공개하지 아니할 수 있다. &lt;신설 2021. 5. 6.&gt;</p><h2 id="article8" class="sr-only" tabindex="-1">제8조 (합격자의 등록) <a class="header-anchor" href="#article8" aria-label="Permalink to &quot;제8조 (합격자의 등록) {#article8 .sr-only}&quot;">​</a></h2><p><strong>제8조(합격자의 등록)</strong> ① 공개경쟁 채용시험 최종 합격자는 대표이사가 정하는 바에 따라 채용후보자등록을 하여야 하며, 등록 후 소정의 절차를 거쳐 채용된다. &lt;개정 2015. 11. 16., 2023. 6. 29.&gt;<br> ② 제1항의 채용후보자등록을 하지 아니하면 임용될 의사가 없는 것으로 본다.</p><h2 id="article9" class="sr-only" tabindex="-1">제9조 (특별채용의 요구) <a class="header-anchor" href="#article9" aria-label="Permalink to &quot;제9조 (특별채용의 요구) {#article9 .sr-only}&quot;">​</a></h2><p><strong>제9조(특별채용의 요구)</strong> 삭제 &lt;2013. 10. 31.&gt;</p><h2 id="article10" class="sr-only" tabindex="-1">제10조 (특별채용의 방법) <a class="header-anchor" href="#article10" aria-label="Permalink to &quot;제10조 (특별채용의 방법) {#article10 .sr-only}&quot;">​</a></h2><p><strong>제10조(특별채용의 방법)</strong> 삭제 &lt;2013. 10. 31.&gt;</p><h2 id="article11" class="sr-only" tabindex="-1">제11조 (재심의 청구) <a class="header-anchor" href="#article11" aria-label="Permalink to &quot;제11조 (재심의 청구) {#article11 .sr-only}&quot;">​</a></h2><p><strong>제11조(재심의 청구)</strong> 삭제 &lt;2013. 10. 31.&gt;</p><h2 id="article12" class="sr-only" tabindex="-1">제12조 (채용자료 보관) <a class="header-anchor" href="#article12" aria-label="Permalink to &quot;제12조 (채용자료 보관) {#article12 .sr-only}&quot;">​</a></h2><p><strong>제12조(채용자료 보관)</strong> 채용 관련 문서를 영구적으로 보존하도록 보존기간을 정하여야 한다. 다만, 응시자가 제출한 서류에 대해서는&quot;채용 절차의 공정화에 관한 법률&quot;에서 정한 바에 따라 반환 또는 폐기하는 경우를 제외하고는 최소 5년 이상 보관하여야 한다. &lt;신설 2018. 10. 10.&gt;, &lt;개정 2019. 8. 14., 2021. 5. 6.&gt;</p><h2 id="addendum1" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum1" aria-label="Permalink to &quot;부칙 {#addendum1 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong><br> 이 내규는 2010년 08월 16일부터 시행한다.</p><h2 id="addendum2" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum2" aria-label="Permalink to &quot;부칙 {#addendum2 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2011. 11. 22.&gt;<br> 이 내규는 2011년 11월 22일부터 시행한다.</p><h2 id="addendum3" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum3" aria-label="Permalink to &quot;부칙 {#addendum3 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2013. 10. 31.&gt;<br> 이 내규는 2013년 10월 31일부터 시행한다.</p><h2 id="addendum4" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum4" aria-label="Permalink to &quot;부칙 {#addendum4 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2015. 11. 16.&gt;<br> 이 내규는 2015년 11월 16일부터 시행한다.</p><h2 id="addendum5" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum5" aria-label="Permalink to &quot;부칙 {#addendum5 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2018. 8. 13.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum6" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum6" aria-label="Permalink to &quot;부칙 {#addendum6 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2019. 8. 14.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum7" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum7" aria-label="Permalink to &quot;부칙 {#addendum7 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2021. 5. 6.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum8" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum8" aria-label="Permalink to &quot;부칙 {#addendum8 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2022. 4. 4.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum9" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum9" aria-label="Permalink to &quot;부칙 {#addendum9 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2022. 8. 23.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum10" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum10" aria-label="Permalink to &quot;부칙 {#addendum10 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2022. 6. 29.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum11" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum11" aria-label="Permalink to &quot;부칙 {#addendum11 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2024. 2. 6.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum12" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum12" aria-label="Permalink to &quot;부칙 {#addendum12 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2024. 7. 24.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum13" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum13" aria-label="Permalink to &quot;부칙 {#addendum13 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2024. 12. 30.&gt;<br> 이 내규는 대표이사 승인을 득한 날로부터 시행한다.</p><h2 id="addendum14" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum14" aria-label="Permalink to &quot;부칙 {#addendum14 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2025. 5. 20.&gt;<br> 이 내규는 대표이사 승인을 받은 날로부터 시행한다.</p><h2 id="addendum15" class="sr-only" tabindex="-1">부칙 <a class="header-anchor" href="#addendum15" aria-label="Permalink to &quot;부칙 {#addendum15 .sr-only}&quot;">​</a></h2><p><strong>부칙</strong> &lt;개정 2025. 08. 12.&gt;<br> 이 내규는 대표이사 승인을 받은 날로부터 시행한다.</p><p><strong>[별표 1]</strong> &lt;신설 2025. 5. 20.&gt; <strong>전형별 부가가점 기준</strong></p><p style="text-align:center;">전형별 부가가점 기준</p><table style="border-collapse:collapse;border:1px solid #000;width:100%;table-layout:auto;"><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;"><strong>구분</strong></p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;"><strong>관련 법률</strong></p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;"><strong>가점비율</strong></p></th></tr><tr><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">취업지원대상자</p><p style="margin:0;text-align:center;">(국가유공자 등 예우 및 지원에 관한 법률)</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">ㅇ「국가유공자등예우및지원에관한법률」제31조</p><p style="margin:0;text-align:left;">ㅇ「독립유공자예우에관한법률」제16조</p><p style="margin:0;text-align:left;">ㅇ「보훈보상대상자지원에관한법률」제35조</p><p style="margin:0;text-align:left;">ㅇ「고엽제후유의증등환자지원및단체설립에관한법률」제7조의9</p><p style="margin:0;text-align:left;">ㅇ「특수임무유공자예우및단체설립에관한법률」제24조</p><p style="margin:0;text-align:left;">ㅇ「5·18민주유공자예우에관한법률」제22조에 해당하는 자</p></th><th style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">각 전형별</p><p style="margin:0;text-align:center;">만점의 5% 또는 10%</p><p style="margin:0;text-align:left;"></p></th></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">장애인</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">ㅇ장애인고용촉진 및 직업재활법 시행령 제3조에 해당하는 자</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">각 전형별</p><p style="margin:0;text-align:center;">만점의 3%</p></td></tr><tr><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">저소득층</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">ㅇ국민기초생활보장법 제2조제2호에 따른 기초생활 보장 수급자</p></td><td style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:center;">각 전형별</p><p style="margin:0;text-align:center;">만점의 3%</p></td></tr><tr><td colspan="3" style="border-top:1px solid #000;border-bottom:1px solid #000;border-left:1px solid #000;padding:2px 4px;vertical-align:middle;border-right:1px solid #000;"><p style="margin:0;text-align:left;">ㅇ 가산대상이 2개 이상 중복되는 경우는 증빙자료를 구비하여 제출한 가산대상에 한하여 가장 유리한 1개까지만 적용</p><p style="margin:0;text-align:left;">ㅇ 국가유공자 등 예우 및 지원에 관한 법률 제31조 제3항에 의거 가점을 받아 채용시험에 합격하는 사람은 채용시험 선발예정인원의 30%를 초과할 수 없음 (단, 응시자수가 선발예정인원과 같거나 그보다 적은 경우에는 가점을 받아 채용시험에 합격한 사람은 채용시험 선발예정인원의 30%를 초과할 수 있음)</p><p style="margin:0;text-align:left;">※ 가점부여 방식 및 기준은 해당 관계 법령의 기준 및 가이드라인에 따른다.</p></td></tr></table>`,68)]))}const b=l(o,[["render",d]]);export{c as __pageData,b as default};
